@testset "all three normals" begin
    # cubic grid, off-centre loop: m = ½ Σ r × dl over the marked edges is the
    # magnetic moment of the staircase; for a positive current it points along the
    # normal, with magnitude close to πR²
    g = create_domain([30.0, 30.0, 30.0], [0.5, 0.5, 0.5])
    function moment(J)
        nodes, edges = (g.nodes_u, g.nodes_v, g.nodes_w), (g.edges_u, g.edges_v, g.edges_w)
        m = zeros(3)
        for p in findall(!iszero, J)
            b, i, j, k = _wire_ijk(g, p)
            from = [nodes[a][(i, j, k)[a]] for a in 1:3]
            dl = [a == b ? edges[a][(i, j, k)[a]] : 0.0 for a in 1:3]
            m .+= cross(from .+ dl ./ 2, dl) .* (J[p] / 2)
        end
        return m
    end
    centre = (14.3, 15.2, 14.9)
    for (a, normal) in enumerate((DirX(), DirY(), DirZ()))
        Jn = @test_logs _loop_source(g, centre..., 8.0, normal)          # and no warnings
        @test iszero(get_divergence(g, Dual()) * Jn)                     # closed
        @test all(x -> x == 1 || x == -1, Jn[findall(!iszero, Jn)])
        m = moment(Jn)
        @test m[a] ≈ π * 8.0^2 rtol = 0.03                               # along +normal
        @test all(b -> abs(m[b]) < 1e-9 * m[a], filter(!=(a), 1:3))
        # only in-plane edges, all in the node plane nearest to the centre
        nz = [_wire_ijk(g, p) for p in findall(!iszero, Jn)]
        @test all(t -> t[1] != a, nz)
        plane = argmin(abs.((g.nodes_u, g.nodes_v, g.nodes_w)[a] .- centre[a]))
        @test all(t -> t[a + 1] == plane, nz)
    end
end

@testset "complex current" begin
    # same grid and loop as above, in fresh domains so the shared grid stays clean
    mk() = create_domain([20.0, 30.0, 30.0], [1.0, 0.5, 0.5])
    loop!(d; kw...) = create_circular_loop_source!(d, 10.3, 15.2, 14.9, 8.0, DirX(); kw...)
    d = mk()
    unit = get_source(d, loop!(d))                              # 1 A, real

    # a phasor scales the unit loop; the vector becomes complex
    e  = mk()
    Jc = @test_logs get_source(e, loop!(e; current=250.0 - 30.0im))   # and no warnings
    @test Jc isa Vector{ComplexF64}
    @test Jc == (250.0 - 30.0im) .* unit
    @test real(Jc) == 250.0 .* unit && imag(Jc) == -30.0 .* unit
    @test iszero(get_divergence(e, Dual()) * Jc)               # still closed: S̃J = 0

    # the type follows the current, not its value: real stays real, complex stays complex
    for (I, T) in ((2, Float64), (2.5f0, Float64), (1.0 + 2.0im, ComplexF64),
                   (ComplexF32(1, 2), ComplexF64), (5.0 + 0.0im, ComplexF64))
        f = mk()
        id = loop!(f; current=I)
        @test only(list_objects(f)).object isa CircularLoop{T}
        @test eltype(get_source(f, id)) == T
        @test get_source(f, id) == I .* unit
    end

    # shown in the object table
    g = mk()
    loop!(g; current=250.0 - 30.0im, name="ac")
    @test occursin("I=250.0 - 30.0im A", repr(MIME"text/plain"(), list_objects(g)))
end

